// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;

/** When the commit log notifies its listener: a seal of an unconfirmed record is not yet applier work. */
class AdjacencyCommitLogNotificationTest {

	private static final class CountingListener implements AdjacencyCommitLog.Listener {
		final AtomicInteger changed = new AtomicInteger();
		final AtomicInteger confirmed = new AtomicInteger();

		@Override
		public void changed() {
			changed.incrementAndGet();
		}

		@Override
		public void confirmed() {
			confirmed.incrementAndGet();
		}
	}

	private static AdjacencyDelta emptyDelta(long revision) {
		return new AdjacencyDelta() {
			@Override
			public long revision() {
				return revision;
			}

			@Override
			public boolean overflowed() {
				return false;
			}

			@Override
			public boolean empty() {
				return true;
			}

			@Override
			public long bytes() {
				return 0;
			}

			@Override
			public Object pending() {
				return null;
			}

			@Override
			public void releaseRows() {
			}
		};
	}

	@Test
	void aSealThatCompletesBeforeConfirmNotifiesOnlyThroughConfirm() {
		AdjacencyCommitLog log = new AdjacencyCommitLog(0);
		CountingListener listener = new CountingListener();
		log.setListener(listener);

		// a small transaction seals on the committing thread while it is staged: the applier cannot act on a record
		// that is not confirmed, so waking it here only costs a wake-up and a race with the committer's own apply
		log.stage(1, CompletableFuture.completedFuture(emptyDelta(1)));
		assertThat(listener.changed).hasValue(0);
		assertThat(listener.confirmed).hasValue(0);

		log.confirm();
		assertThat(listener.confirmed).hasValue(1);
		assertThat(listener.changed).hasValue(0);
	}

	@Test
	void aSealThatCompletesAfterConfirmNotifiesAChange() {
		AdjacencyCommitLog log = new AdjacencyCommitLog(0);
		CountingListener listener = new CountingListener();
		log.setListener(listener);
		CompletableFuture<AdjacencyDelta> sealing = new CompletableFuture<>();

		log.stage(1, sealing);
		log.confirm();
		assertThat(listener.confirmed).hasValue(1);
		assertThat(listener.changed).hasValue(0);

		// the record became applier work only now
		sealing.complete(emptyDelta(1));
		assertThat(listener.changed).hasValue(1);
	}
}
